package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="fund_reservations") public class FundReservation{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@OneToOne(optional=false) @JoinColumn(name="transfer_id",unique=true) private TransferTransaction transfer;@ManyToOne(optional=false) private TransferAccount account;@Column(nullable=false,precision=19,scale=4) private BigDecimal amount;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ReservationStatus status;@Column(name="expires_at",nullable=false) private Instant expiresAt;@Column(name="created_at",nullable=false) private Instant createdAt;@PrePersist void create(){createdAt=Instant.now();}public void setTransfer(TransferTransaction v){transfer=v;}public void setAccount(TransferAccount v){account=v;}public void setAmount(BigDecimal v){amount=v;}public void setStatus(ReservationStatus v){status=v;}public void setExpiresAt(Instant v){expiresAt=v;}public ReservationStatus getStatus(){return status;}public enum ReservationStatus{ACTIVE,CONSUMED,RELEASED,EXPIRED}}
